import { useState } from 'react';
import { Image, Pressable, TextInput, View } from 'react-native';
import { useRouter } from 'expo-router';
import { useQuery } from '@tanstack/react-query';
import { Heart, MagnifyingGlass, SealCheck, SlidersHorizontal, Star } from 'phosphor-react-native';

import { api, apiMessage } from '@/lib/api';
import { useCatalogCategories } from '@/components/business/category-picker';
import { rupees } from '@/lib/format';
import { Alert, Caption, Card, EmptyState, Loading, PageSubtitle, PageTitle, Screen, SectionTitle } from '@/components/ui';
import { rgb, space, useTheme } from '@/theme';
type Vendor = { id: string; name: string; category: string | null; categories?: string[]; city?: string; description?: string; ratingAvg: number; ratingCount: number; portfolio?: string[]; startingPrice?: number | null; verifiedAt?: string | null };
export default function Vendors() { const theme = useTheme(); const router = useRouter(); const [search, setSearch] = useState(''); const [category, setCategory] = useState(''); const [filters, setFilters] = useState(false); const [city, setCity] = useState(''); const catalog = useCatalogCategories(); const q = useQuery({ queryKey: ['vendors', category, city, search], queryFn: async () => (await api.get('/vendors/search', { params: { category: category || undefined, city: city || undefined, search: search || undefined, limit: 30 } })).data, retry: false }); const vendors: Vendor[] = q.data?.data ?? [];
return <Screen><View><PageTitle>Vendors</PageTitle><PageSubtitle>Find the best vendors for your special day</PageSubtitle></View><View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: rgb(theme.surface), borderRadius: 22, paddingLeft: space(3) }}><MagnifyingGlass size={18} color={rgb(theme.brand)} /><TextInput value={search} onChangeText={setSearch} placeholder="Search vendors..." placeholderTextColor={rgb(theme.ink[400])} style={{ flex: 1, padding: space(3), color: rgb(theme.ink[900]) }} /><Pressable onPress={() => setFilters(!filters)} style={{ marginRight: space(1), padding: space(2), borderRadius: 20, backgroundColor: rgb(theme.brand) }}><SlidersHorizontal size={18} color={rgb(theme.brandFg)} /></Pressable></View>{filters ? <Card><Caption>Location</Caption><TextInput value={city} onChangeText={setCity} placeholder="Any city" placeholderTextColor={rgb(theme.ink[400])} style={{ paddingVertical: space(2), color: rgb(theme.ink[900]) }} /><Caption tone="faint">The existing vendor API supports category, city, search and sort. Distance, amenity and rating filters are not exposed.</Caption></Card> : null}<View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: space(2) }}>{catalog.isPending ? <Loading rows={2} /> : catalog.data?.map((item) => <Pressable key={item.slug} onPress={() => setCategory(category === item.slug ? '' : item.slug)} style={{ width: '30.7%' }}><Card style={{ padding: space(2), alignItems: 'center', backgroundColor: category === item.slug ? rgb(theme.brandSoft) : rgb(theme.surface) }}><Caption tone={category === item.slug ? 'brand' : 'muted'} style={{ textAlign: 'center' }}>{item.name}</Caption></Card></Pressable>)}</View><SectionTitle>Featured Vendors</SectionTitle>{q.isPending ? <Loading rows={3} /> : q.error ? <Alert tone="critical">{apiMessage(q.error, 'Vendors could not be loaded.')}</Alert> : vendors.length ? vendors.map((v) => <Pressable key={v.id} onPress={() => router.push({ pathname: '/vendors/[id]', params: { id: v.id } })}><Card style={{ flexDirection: 'row', padding: space(2) }}>{v.portfolio?.[0] ? <Image source={{ uri: v.portfolio[0] }} style={{ width: 94, height: 94, borderRadius: 12 }} /> : <View style={{ width: 94, height: 94, borderRadius: 12, backgroundColor: rgb(theme.surfaceSunken) }} />}<View style={{ flex: 1, gap: 3 }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}><Caption style={{ fontWeight: '700', color: rgb(theme.ink[800]) }}>{v.name}</Caption>{v.verifiedAt ? <SealCheck size={14} color={rgb(theme.positiveFg)} weight="fill" /> : null}</View><Caption><Star size={12} color={rgb(theme.brand)} weight="fill" /> {v.ratingAvg.toFixed(1)} ({v.ratingCount} reviews)</Caption><Caption tone="faint">{[v.city, v.category].filter(Boolean).join(' · ')}</Caption>{v.startingPrice ? <Caption tone="brand">From {rupees(v.startingPrice)}</Caption> : null}</View><Heart size={19} color={rgb(theme.brand)} /></Card></Pressable>) : <EmptyState title="No vendors found">Try another category, city, or search term.</EmptyState>}</Screen>; }
